parameters.html:
=<!DOCTYPE html>
<html lang='en'>
<head>
<meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1'>
<title>Daily Briefing</title>
<style>
body { margin:0; padding:24px 12px; background:#eef1f6; color:#151a21; font-family:-apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif; line-height:1.45 }
.wrap { max-width:760px; margin:0 auto }
.hero { background:#151a21; color:#ffffff; border-radius:14px; padding:22px 24px }
.hero .day { font-size:12px; letter-spacing:.12em; text-transform:uppercase; opacity:.65 }
.hero h1 { margin:6px 0 0; font-size:23px; line-height:1.25 }
.focus { margin-top:14px; padding:10px 14px; background:#2b6cf6; border-radius:9px; font-size:14px }
.stats { width:100%; margin-top:16px; border-collapse:separate; border-spacing:10px 0 }
.stats td { background:#ffffff; border-radius:11px; padding:14px 8px; text-align:center; width:25% }
.stats .n { display:block; font-size:22px; font-weight:700 }
.stats .k { display:block; font-size:11px; letter-spacing:.07em; text-transform:uppercase; color:#68717f; margin-top:3px }
.card { background:#ffffff; border-radius:13px; padding:18px 20px; margin-top:16px }
.card h2 { margin:0 0 12px; font-size:13px; letter-spacing:.09em; text-transform:uppercase; color:#68717f }
.card ol, .card ul { margin:0; padding:0; list-style:none }
.card li { padding:11px 0; border-top:1px solid #eceff4 }
.card li:first-child { border-top:0; padding-top:0 }
.card li strong { display:block; font-size:15px }
.card li em { display:block; font-style:normal; font-size:13px; color:#5c6673; margin-top:2px }
.card li b { display:inline-block; font-size:11px; letter-spacing:.06em; text-transform:uppercase; color:#2b6cf6; margin-bottom:3px }
.card li code { display:inline-block; min-width:54px; font:600 14px/1.4 SFMono-Regular, Menlo, Consolas, monospace }
.warn li strong { color:#b3450b }
.empty { color:#8a929d; font-size:13px }
footer { color:#8a929d; font-size:11px; text-align:center; margin-top:18px }
</style>
</head>
<body>
<div class='wrap'>
<div class='hero'>
<div class='day'>{{ $now.toFormat('cccc d LLLL yyyy') }}</div>
<h1>{{ ($json.output?.headline ?? 'Your daily briefing').replace(/</g, '&lt;') }}</h1>
<div class='focus'>First thing: {{ ($json.output?.focus ?? 'Nothing urgent today').replace(/</g, '&lt;') }}</div>
</div>
<table class='stats'><tr>
<td><span class='n'>{{ $json.output?.stats?.emails ?? 0 }}</span><span class='k'>Emails</span></td>
<td><span class='n'>{{ $json.output?.stats?.needsReply ?? 0 }}</span><span class='k'>To answer</span></td>
<td><span class='n'>{{ $json.output?.stats?.events ?? 0 }}</span><span class='k'>Meetings</span></td>
<td><span class='n'>{{ $json.output?.stats?.busyHours ?? '0h' }}</span><span class='k'>Booked</span></td>
</tr></table>
<div class='card'><h2>Priorities</h2><ol>{{ ($json.output?.priorities ?? []).map(p => '<li><b>' + (p.source ?? '') + '</b><strong>' + (p.title ?? '').replace(/</g, '&lt;') + '</strong><em>' + (p.detail ?? '').replace(/</g, '&lt;') + '</em></li>').join('') || '<li class=empty>Nothing ranked for today</li>' }}</ol></div>
<div class='card'><h2>Schedule</h2><ul>{{ ($json.output?.schedule ?? []).map(s => '<li><code>' + (s.time ?? '').replace(/</g, '&lt;') + '</code><strong>' + (s.title ?? '').replace(/</g, '&lt;') + '</strong><em>' + (s.detail ?? '').replace(/</g, '&lt;') + '</em></li>').join('') || '<li class=empty>No meetings today</li>' }}</ul></div>
<div class='card'><h2>Inbox</h2><ul>{{ ($json.output?.inboxHighlights ?? []).map(h => '<li><b>' + (h.bucket ?? '').replace(/</g, '&lt;') + '</b><strong>' + (h.title ?? '').replace(/</g, '&lt;') + '</strong><em>' + (h.detail ?? '').replace(/</g, '&lt;') + '</em></li>').join('') || '<li class=empty>Inbox is clear</li>' }}</ul></div>
<div class='card warn'><h2>Watch out</h2><ul>{{ ($json.output?.watchOuts ?? []).map(w => '<li><strong>' + (w + '').replace(/</g, '&lt;') + '</strong></li>').join('') || '<li class=empty>No conflicts detected</li>' }}</ul></div>
<footer>Assembled by the Email Triage Agent, the Calendar Agent and the Briefing Editor Agent.</footer>
</div>
</body>
</html>
